+    }
+    let t0 = t0.clamp(0.0, 1.0);
+    let t1 = t1.clamp(0.0, 1.0);
+    if t1 <= t0 {
+        return None;
+    }
+    let d = sub3(p1, p0);
+    let at = |t: f64| add3(p0, scale3(d, t));
+    Some((at(t0), at(t1)))
+}

